const item = $input.first().json;

// Stage 02: Research Preparation
const researchPrompt = `You are the Lead Researcher for a YouTube content automation pipeline.
Gather accurate, high-retention facts, hooks, and narrative structures for:
Topic: ${item.topic}
Target Duration: ${item.target_duration}
Language: ${item.language}
Style: ${item.style}

Provide the response in strict JSON format matching the schema in prompts/research/system_prompt.md.`;

return {
  json: {
    ...item,
    research_prompt: researchPrompt,
    stage: '02_research'
  }
};

const item = $input.first().json;

// Mock or router response for Research Agent
const mockResearchOutput = {
  topic: item.topic,
  hook_angles: [
    "What if our universe is actually inside a black hole?",
    "Time stops completely at the event horizon — but why?"
  ],
  core_facts: [
    {
      fact: "Supermassive black holes like Sagittarius A* anchor galaxies with millions of solar masses.",
      context: "Discovered at the center of the Milky Way."
    },
    {
      fact: "Spaghettification stretches matter infinitely due to extreme tidal gravity differences.",
      context: "Astrophysical phenomenon first coined by Stephen Hawking."
    },
    {
      fact: "Black holes can slowly evaporate over trillions of years via Hawking Radiation.",
      context: "Theoretical quantum effect at the event horizon."
    }
  ],
  narrative_arc: [
    { section: "Intro", focus: "Curiosity hook: The monster in the cosmic dark" },
    { section: "Fact 1 & 2", focus: "Scale, event horizons, and gravity distortion" },
    { section: "Fact 3 & 4", focus: "Spaghettification and time dilation" },
    { section: "Fact 5 & Outro", focus: "Hawking radiation and the cosmic horizon" }
  ]
};

return {
  json: {
    ...item,
    research_data: mockResearchOutput,
    stage: '02_research_completed'
  }
};

const item = $input.first().json;

// Stage 03: Scriptwriter Agent
const fullNarration = `Imagine a place where gravity is so intense that not even light can escape. A boundary beyond which time itself grinds to a halt. Welcome to the mysterious world of black holes. At the very center of our galaxy lies Sagittarius A*, a gargantuan cosmic monster containing the mass of over four million suns. But what would actually happen if you fell in? First, extreme gravitational gradients would stretch you out in a process astrophysicists literally call spaghettification. As you cross the event horizon, an outside observer would see you freeze in time forever. Yet, these titans aren't eternal. Through Hawking radiation, black holes slowly lose energy over trillions of years until they vanish with a final cosmic flash. The universe is far stranger than we can imagine.`;

const wordCount = fullNarration.trim().split(/\s+/).length;

return {
  json: {
    ...item,
    script: {
      title: item.topic,
      word_count: wordCount,
      estimated_duration_seconds: Math.round((wordCount / 145) * 60),
      narration_text: fullNarration
    },
    stage: '03_script_generated'
  }
};

const item = $input.first().json;

// Stage 04: Script QC Agent
const script = item.script;
const passedPacing = script.word_count >= 50;

const qcReport = {
  passed: passedPacing,
  quality_score: 95,
  retention_assessment: "High opening hook retention, clean spoken cadence.",
  approved_text: script.narration_text
};

return {
  json: {
    ...item,
    qc_report: qcReport,
    stage: '04_qc_approved'
  }
};

const item = $input.first().json;

// Stage 05: TTS Synthesis Router
const ttsPlan = {
  provider: 'edge-tts',
  voice: 'en-US-ChristopherNeural',
  rate: '+0%',
  pitch: '+0Hz',
  text_to_synthesize: item.qc_report.approved_text,
  output_format: 'mp3',
  target_lufs: -14.0
};

return {
  json: {
    ...item,
    tts_plan: ttsPlan,
    stage: '05_tts_ready'
  }
};
